/bin/bash -lc 'set -e
work_tmp="${TMPDIR:-/tmp}/khategaon_verify_7317"
out=$(ls -t "$work_tmp"/search_*.html | head -1)
python3 - "$out" <<'"'PY'
from html.parser import HTMLParser
from pathlib import Path
import sys
class P(HTMLParser):
 def __init__(self): super().__init__(); self.in_a=False; self.cur=None; self.a=[]
 def handle_starttag(self,tag,attrs):
  if tag=='a': self.in_a=True; self.cur=[dict(attrs).get('href',''), '']
 def handle_endtag(self,tag):
  if tag=='a' and self.cur: self.a.append(tuple(self.cur)); self.cur=None; self.in_a=False
 def handle_data(self,d):
  if self.in_a and self.cur:
   d=' '.join(d.split())
   if d: self.cur[1]+=(' '+d)
p=P(); p.feed(Path(sys.argv[1]).read_text(errors='ignore'))
for u,t in p.a:
 if t.strip(): print(t.strip(),'\\t',u)
PY"

